CREATE DATABASE IF NOT EXISTS playvault CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE playvault;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,platform VARCHAR(50) NOT NULL,genre VARCHAR(50) NOT NULL,region VARCHAR(50) NOT NULL,image_url VARCHAR(600) NOT NULL,rating DECIMAL(2,1) NOT NULL DEFAULT 4.5,popularity INT NOT NULL DEFAULT 0,search_terms TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS offers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,seller_name VARCHAR(100) NOT NULL,price DECIMAL(8,2) NOT NULL,region VARCHAR(50) NOT NULL,delivery_time VARCHAR(40) NOT NULL DEFAULT 'Instant delivery',rating DECIMAL(2,1) NOT NULL DEFAULT 4.8,stock INT NOT NULL DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id),INDEX(product_id,price)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS digital_keys(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,offer_id BIGINT UNSIGNED NOT NULL,key_value VARCHAR(100) NOT NULL UNIQUE,is_sold TINYINT(1) NOT NULL DEFAULT 0,order_id BIGINT UNSIGNED NULL,FOREIGN KEY(offer_id) REFERENCES offers(id),INDEX(offer_id,is_sold)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,total DECIMAL(8,2) NOT NULL,status ENUM('paid','refunded') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,offer_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,unit_price DECIMAL(8,2) NOT NULL,quantity INT NOT NULL,key_value VARCHAR(100) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(offer_id) REFERENCES offers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS home_blocks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,block_key ENUM('hero','bestsellers','deals') NOT NULL,title VARCHAR(160) NOT NULL,subtitle VARCHAR(255) NOT NULL DEFAULT '',image_url VARCHAR(600) NOT NULL DEFAULT '',tag VARCHAR(50) NOT NULL DEFAULT '',product_id BIGINT UNSIGNED NULL,sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
